const text = $json.text;

const cleaned = text
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const data = JSON.parse(cleaned);

return {
  json: {
    company_name: data.company_name,
    industry: data.industry,
    lead_score: data.lead_score,
    potential_services: Array.isArray(data.potential_services)
      ? data.potential_services.join(', ')
      : data.potential_services,
    reason: data.reason,
    outreach_angle: data.outreach_angle
  }
};
